// === Tab: mySketch ===
const fMar = 0.1; // margin percent
const fDevi = 0.725; // deviation noise scale
const fN1 = 0.0085123;
const fN2 = 0.0075936;

function setup() {
  createCanvas((S = max(windowWidth, windowHeight)), S);
  M = S * fMar;
  describe("lines from top (less noise) to bottom (more noise) increasing noise from left to right");
}

function draw() {
  background(32);
  strokeWeight(1.5);
  stroke("rgba(192,8,24,0.125)");

  // console.log(M, M * fDevi);
  for (let x = width * fMar; x < width * (1 - fMar); x += 0.25) {
    const fScl = x / width * 2;
    const dx = (noise(x * fN1) - 0.5) * M * fDevi * fScl;
    const dy = (noise(x * fN2 + TWO_PI) - 0.5) * M * fDevi * fScl;
    // console.log(nf(dx, 0, 0), nf(dy, 0, 0));
    line(x + dx * 0.5, M + dy * 0.5, x + dx * 2, height - M + dy * 2);
  }

  // noLoop() removed for animation
}
